CREATE TABLE assist_policies(account TEXT PRIMARY KEY,revision INTEGER NOT NULL,mode TEXT NOT NULL,summaries INTEGER NOT NULL,categories_json TEXT NOT NULL,FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE assist_results(account TEXT NOT NULL,request_id TEXT NOT NULL,conversation_id TEXT NOT NULL,request_fingerprint TEXT NOT NULL,snapshot_json TEXT NOT NULL,output_sha256 TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(account,request_id),FOREIGN KEY(account,conversation_id) REFERENCES conversations(account,id));
CREATE TABLE assist_category_intents(account TEXT NOT NULL,message_id TEXT NOT NULL,category_id TEXT NOT NULL,value INTEGER NOT NULL,revision INTEGER NOT NULL,request_id TEXT NOT NULL,PRIMARY KEY(account,message_id,category_id),FOREIGN KEY(account,message_id) REFERENCES messages(account,id),FOREIGN KEY(account,category_id) REFERENCES categories(account,id));
